function primaryStyleImg(key) {
  const imgs = styleInfoImgs[key];
  return Array.isArray(imgs) ? imgs[0] : imgs;
}
function randomStyleImg(key) {
  const imgs = styleInfoImgs[key];
  if (!Array.isArray(imgs)) return imgs;
  return imgs[Math.floor(Math.random() * imgs.length)];
}
function showStyleInfo(key) {
  showPopup(t('style.' + key), t('styleDesc.' + key), primaryStyleImg(key));
}

const quizStyleKeys = ['scandinavian', 'minimalism', 'loft', 'classic', 'japandi', 'boho'];
let quizRounds = [];
let quizIndex = 0;
let quizScores = {};
let quizExcluded = [];
let quizTopKey = null;

function buildQuizRounds(pool, count) {
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  const rounds = [];
  for (let i = 0; i < count; i++) {
    const a = shuffled[i % shuffled.length];
    let b = shuffled[(i + 2) % shuffled.length];
    if (b === a) b = shuffled[(shuffled.indexOf(a) + 1) % shuffled.length];
    rounds.push([a, b]);
  }
  return rounds;
}

function openQuizModal() {
  quizExcluded = [];
  quizRounds = buildQuizRounds(quizStyleKeys, 5);
  quizIndex = 0;
  quizScores = {};
  document.getElementById('quizResult').style.display = 'none';
  document.getElementById('quizConfirm').style.display = 'none';
  document.getElementById('quizPair').style.display = 'grid';
  renderQuizRound();
  document.getElementById('quizModal').classList.add('visible');
}
function closeQuizModal() {
  document.getElementById('quizModal').classList.remove('visible');
  if (pendingOnboarding) {
    pendingOnboarding = false;
    setTimeout(startOnboarding, 300);
  }
}

const onboardingSteps = [
  { id: 'uploadZone', label: 'Шаг 1', text: 'Загрузите фото своей комнаты — нажмите сюда или перетащите файл.' },
  { id: 'styleSection', label: 'Шаг 2', text: 'Выберите стиль интерьера — один из вариантов.' },
  { id: 'roomSection', label: 'Шаг 3', text: 'Укажите тип комнаты, которую переделываем.' },
  { id: 'colorSection', label: 'Шаг 4', text: 'Выберите цветовую палитру для дизайна.' },
  { id: 'genBtn', label: 'Шаг 5', text: 'Когда всё готово — нажмите «Создать дизайн». Результат появится примерно через 30 секунд, с подобранной мебелью и ссылками на неё.' }
];
let onboardingIndex = 0;
let pendingOnboarding = false;

function positionOnboardingStep(i) {
  const step = onboardingSteps[i];
  const el = document.getElementById(step.id);
  if (!el) { nextOnboardingStep(); return; }
  el.scrollIntoView({ behavior: 'instant', block: 'center' });
  setTimeout(() => {
    const r = el.getBoundingClientRect();
    const spot = document.getElementById('onboardingSpotlight');
    spot.style.left = (r.left - 8) + 'px';
    spot.style.top = (r.top - 8) + 'px';
    spot.style.width = (r.width + 16) + 'px';
    spot.style.height = (r.height + 16) + 'px';

    document.getElementById('onboardingStepLabel').textContent = step.label;
    document.getElementById('onboardingText').textContent = step.text;
    document.getElementById('onboardingNextBtn').textContent = i === onboardingSteps.length - 1 ? 'Понятно' : 'Далее';

    const tip = document.getElementById('onboardingTooltip');
    const tipWidth = 260;
    let tipTop = r.bottom + 18;
    if (tipTop + 140 > window.innerHeight) tipTop = Math.max(16, r.top - 150);
    let tipLeft = r.left;
    if (tipLeft + tipWidth + 20 > window.innerWidth) tipLeft = window.innerWidth - tipWidth - 20;
    tipLeft = Math.max(16, tipLeft);
    tip.style.top = tipTop + 'px';
    tip.style.left = tipLeft + 'px';
  }, 60);
}
function nextOnboardingStep() {
  onboardingIndex++;
  if (onboardingIndex >= onboardingSteps.length) { endOnboarding(); return; }
  positionOnboardingStep(onboardingIndex);
}
function skipOnboarding() { endOnboarding(); }
function endOnboarding() {
  document.getElementById('onboardingOverlay').style.display = 'none';
  try { localStorage.setItem('rf_onboarding_done', '1'); } catch (e) {}
}
function startOnboarding() {
  let done = false;
  try { done = localStorage.getItem('rf_onboarding_done') === '1'; } catch (e) {}
  if (done) return;
  showHome();
  onboardingIndex = 0;
  document.getElementById('onboardingOverlay').style.display = 'block';
  positionOnboardingStep(0);
}
function renderQuizRound() {
  document.getElementById('quizProgress').textContent = (quizIndex + 1) + ' / ' + quizRounds.length;
  const [a, b] = quizRounds[quizIndex];
  const pair = document.getElementById('quizPair');
  pair.innerHTML = [a, b].map(key =>
    '<button type="button" class="quiz-option" data-key="' + key + '">' +
      '<img src="' + randomStyleImg(key) + '" alt="">' +
      '<span>' + t('style.' + key) + '</span>' +
    '</button>'
  ).join('');
  pair.querySelectorAll('.quiz-option').forEach(btn => {
    btn.addEventListener('click', () => {
      const key = btn.dataset.key;
      quizScores[key] = (quizScores[key] || 0) + 1;
      quizIndex++;
      if (quizIndex < quizRounds.length) renderQuizRound();
      else showQuizConfirm();
    });
  });
}
function showQuizConfirm() {
  const ranked = Object.entries(quizScores).sort((a, b) => b[1] - a[1]);
  quizTopKey = ranked.length ? ranked[0][0] : quizStyleKeys.find(k => !quizExcluded.includes(k));
  document.getElementById('quizPair').style.display = 'none';
  document.getElementById('quizConfirmText').textContent = t('quiz.resultPrefix') + ' ' + t('style.' + quizTopKey) + '.';
  document.getElementById('quizConfirm').style.display = 'block';
}
function quizAgree() {
  document.getElementById('quizConfirm').style.display = 'none';
  finishQuiz(quizTopKey);
}
function quizDisagree() {
  if (quizTopKey) quizExcluded.push(quizTopKey);
  const pool = quizStyleKeys.filter(k => !quizExcluded.includes(k));
  if (pool.length < 2) { finishQuiz(quizTopKey); return; }
  quizRounds = buildQuizRounds(pool, 5);
  quizIndex = 0;
  quizScores = {};
  document.getElementById('quizConfirm').style.display = 'none';
  document.getElementById('quizPair').style.display = 'grid';
  renderQuizRound();
}
async function finishQuiz(topKey) {
  try { localStorage.setItem('rf_quiz_prompted', '1'); } catch (e) {}
  document.getElementById('quizPair').style.display = 'none';
  document.getElementById('quizConfirm').style.display = 'none';
  document.getElementById('quizResultText').textContent = t('quiz.resultPrefix') + ' ' + t('style.' + topKey) + '.';
  document.getElementById('quizResult').style.display = 'block';
  if (currentSession) {
    try {
      const { data } = await sb.auth.updateUser({ data: { preferred_style: topKey } });
      if (data && data.user) currentSession.user = data.user;
    } catch (e) {}
  }
  applyPreferredStyle(topKey);
  updatePreferredStyleCheck(currentSession);
  const styleText = document.getElementById('accountStyleText');
  if (styleText) styleText.textContent = t('quiz.resultPrefix') + ' ' + t('style.' + topKey);
}
function applyPreferredStyle(key) {
  const btn = document.querySelector('.opt-btn[data-group="style"][data-key="' + key + '"]');
  if (btn) btn.click();
}

function applyTranslations() {
  document.documentElement.lang = LANG;
  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    el.innerHTML = t(el.getAttribute('data-i18n-html'));
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.placeholder = t(el.getAttribute('data-i18n-placeholder'));
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    el.title = t(el.getAttribute('data-i18n-title'));
  });
  document.querySelectorAll('.lang-btn').forEach(b => b.classList.toggle('active', b.dataset.lang === LANG));

  refreshColorNames();

  const budgetValEl = document.getElementById('budgetVal');
  if (budgetValEl) budgetValEl.textContent = t('budget.' + sel.budget);

  const authSubmitBtn = document.getElementById('authSubmitBtn');
  if (authSubmitBtn) authSubmitBtn.textContent = authMode === 'login' ? t('authSubmitLogin') : t('authSubmitSignup');

  const genBtnEl = document.getElementById('genBtn');
  if (genBtnEl) genBtnEl.textContent = generating ? t('genBtnLoading') : (file ? t('genBtnReady') : t('genBtnUpload'));

  if (document.getElementById('accountView').style.display !== 'none') {
    loadLibrary();
  }

  updatePreferredStyleCheck(currentSession);
}

function setLang(lang) {
  LANG = lang;
  localStorage.setItem('rf_lang', lang);
  applyTranslations();
}

let authMode = 'login';
let currentSession = null;

function openAuthModal() {
  document.getElementById('authModal').classList.add('visible');
}
function closeAuthModal() {
  document.getElementById('authModal').classList.remove('visible');
  document.getElementById('authMsg').textContent = '';
  document.getElementById('authMsg').className = 'auth-msg';
  document.getElementById('authForm').reset();
}
document.getElementById('authModal').addEventListener('click', e => {
  if (e.target === document.getElementById('authModal')) closeAuthModal();
});

function switchAuthTab(mode) {
  authMode = mode;
  const tabs = document.querySelector('.auth-tabs');
  const pwField = document.getElementById('authPassword');
  const forgotLink = document.getElementById('authForgotLink');
  const backLink = document.getElementById('authBackLink');
  const recoveryHint = document.getElementById('authRecoveryHint');
  const emailField = document.getElementById('authEmail');
  const submitBtn = document.getElementById('authSubmitBtn');

  document.getElementById('tabLogin').classList.toggle('active', mode === 'login');
  document.getElementById('tabSignup').classList.toggle('active', mode === 'signup');

  tabs.style.display = (mode === 'login' || mode === 'signup') ? '' : 'none';
  pwField.style.display = (mode === 'reset') ? 'none' : '';
  pwField.required = mode !== 'reset';
  pwField.placeholder = mode === 'recovery' ? t('auth.newPasswordPlaceholder') : t('authPasswordPlaceholder');
  emailField.style.display = mode === 'recovery' ? 'none' : '';
  emailField.required = mode !== 'recovery';
  forgotLink.style.display = mode === 'login' ? '' : 'none';
  backLink.style.display = (mode === 'reset') ? '' : 'none';
  recoveryHint.style.display = mode === 'recovery' ? '' : 'none';
  const consentWrap = document.getElementById('authConsentWrap');
  consentWrap.style.display = mode === 'signup' ? '' : 'none';
  document.getElementById('authConsent').checked = false;

  const submitLabels = { login: 'authSubmitLogin', signup: 'authSubmitSignup', reset: 'auth.sendResetLink', recovery: 'auth.savePassword' };
  submitBtn.textContent = t(submitLabels[mode]);

  document.getElementById('authMsg').textContent = '';
  document.getElementById('authMsg').className = 'auth-msg';
}

function renderAuthArea(session) {
  const area = document.getElementById('authArea');
  area.innerHTML = '<button class="nav-person-btn" type="button" aria-label="Account"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="4"></circle><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"></path></svg></button>';
  const btn = area.querySelector('.nav-person-btn');
  btn.onclick = (session && session.user) ? showAccount : openAuthModal;
}

document.getElementById('authForm').addEventListener('submit', async e => {
  e.preventDefault();
  const email = document.getElementById('authEmail').value.trim();
  const password = document.getElementById('authPassword').value;
  const msg = document.getElementById('authMsg');
  const btn = document.getElementById('authSubmitBtn');
  msg.textContent = '';
  msg.className = 'auth-msg';

  if (authMode === 'signup' && !document.getElementById('authConsent').checked) {
    msg.textContent = t('auth.consentRequired');
    msg.className = 'auth-msg error';
    return;
  }

  btn.disabled = true;

  try {
    if (authMode === 'login') {
      const { error } = await sb.auth.signInWithPassword({ email, password });
      if (error) throw error;
      trackEvent('login');
      closeAuthModal();
    } else if (authMode === 'signup') {
      const { data, error } = await sb.auth.signUp({ email, password, options: { emailRedirectTo: 'https://gwirglemly-beep.github.io/roomfactory/' } });
      if (error) throw error;
      if (data && data.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {
        msg.textContent = t('auth.alreadyExists');
        msg.className = 'auth-msg error';
      } else {
        trackEvent('signup_completed');
        msg.textContent = t('authSuccess');
        msg.className = 'auth-msg success';
      }
    } else if (authMode === 'reset') {
      const { error } = await sb.auth.resetPasswordForEmail(email, { redirectTo: 'https://gwirglemly-beep.github.io/roomfactory/' });
      if (error) throw error;
      msg.textContent = t('auth.resetLinkSent');
      msg.className = 'auth-msg success';
    } else if (authMode === 'recovery') {
      const { error } = await sb.auth.updateUser({ password });
      if (error) throw error;
      msg.textContent = t('auth.passwordSaved');
      msg.className = 'auth-msg success';
      setTimeout(() => { switchAuthTab('login'); closeAuthModal(); }, 1500);
    }
  } catch (err) {
    msg.textContent = err.message || t('authErrorFallback');
    msg.className = 'auth-msg error';
  } finally {
    btn.disabled = false;
  }
});

function updatePreferredStyleCheck(session) {
  const wrap = document.getElementById('preferredStyleCheckWrap');
  const pref = session && session.user && session.user.user_metadata && session.user.user_metadata.preferred_style;
  wrap.style.display = pref ? 'flex' : 'none';
  if (!pref) {
    document.getElementById('usePreferredStyle').checked = false;
  } else {
    document.getElementById('preferredStyleLink').textContent = t('form.preferredStyleLinkPrefix') + ' ' + t('style.' + pref) + ' · ' + t('form.retakeQuizShort');
  }
}

sb.auth.onAuthStateChange((_event, session) => {
  currentSession = session;
  renderAuthArea(session);
  updatePreferredStyleCheck(session);
  if (_event === 'PASSWORD_RECOVERY') {
    openAuthModal();
    switchAuthTab('recovery');
  }
  let quizAlreadyPrompted = false;
  try { quizAlreadyPrompted = localStorage.getItem('rf_quiz_prompted') === '1'; } catch (e) {}
  if (_event === 'SIGNED_IN' && session && session.user && !quizAlreadyPrompted && !(session.user.user_metadata && session.user.user_metadata.preferred_style)) {
    try { localStorage.setItem('rf_quiz_prompted', '1'); } catch (e) {}
    pendingOnboarding = true;
    setTimeout(openQuizModal, 400);
  }
});
sb.auth.getSession().then(({ data }) => {
  currentSession = data.session;
  renderAuthArea(data.session);
  updatePreferredStyleCheck(data.session);
  const pref = data.session && data.session.user && data.session.user.user_metadata && data.session.user.user_metadata.preferred_style;
  if (pref) applyPreferredStyle(pref);
});

document.getElementById('usePreferredStyle').addEventListener('change', e => {
  const pref = currentSession && currentSession.user && currentSession.user.user_metadata && currentSession.user.user_metadata.preferred_style;
  if (e.target.checked && pref) applyPreferredStyle(pref);
});

function openModal(id) {
  document.getElementById(id).classList.add('visible');
}
function closeModal(id) {
  document.getElementById(id).classList.remove('visible');
}
['howModal', 'aboutModal', 'quizModal', 'faqModal'].forEach(id => {
  document.getElementById(id).addEventListener('click', e => {
    if (e.target === document.getElementById(id)) closeModal(id);
  });
});

const LEGAL_VIEW_IDS = ['accountView', 'privacyView', 'offerView', 'consentView'];
function showHome() {
  LEGAL_VIEW_IDS.forEach(id => document.getElementById(id).style.display = 'none');
  document.getElementById('homeView').style.display = '';
}
function showLegalView(id) {
  document.getElementById('homeView').style.display = 'none';
  LEGAL_VIEW_IDS.forEach(vid => document.getElementById(vid).style.display = vid === id ? 'block' : 'none');
  window.scrollTo(0, 0);
}
function showPrivacy() { showLegalView('privacyView'); }
function showOffer() { showLegalView('offerView'); }
function showConsent() { showLegalView('consentView'); }
function showAccount() {
  showLegalView('accountView');
  loadProfile();
  loadLibrary();
}


function loadProfile() {
  if (!currentSession) return;
  const meta = currentSession.user.user_metadata || {};
  document.getElementById('accountEmailField').value = currentSession.user.email || '';
  document.getElementById('profileFirstName').value = meta.first_name || '';
  document.getElementById('profileLastName').value = meta.last_name || '';
  document.getElementById('profilePhone').value = meta.phone || '';
  const styleText = document.getElementById('accountStyleText');
  if (styleText) {
    styleText.textContent = meta.preferred_style ? (t('quiz.resultPrefix') + ' ' + t('style.' + meta.preferred_style)) : t('account.styleNone');
  }
}

document.getElementById('profileForm').addEventListener('submit', async e => {
  e.preventDefault();
  const btn = document.getElementById('profileSaveBtn');
  const msg = document.getElementById('profileMsg');
  btn.disabled = true;
  msg.textContent = '';
  msg.className = 'profile-msg';
  try {
    const { data, error } = await sb.auth.updateUser({
      data: {
        first_name: document.getElementById('profileFirstName').value.trim(),
        last_name: document.getElementById('profileLastName').value.trim(),
        phone: document.getElementById('profilePhone').value.trim()
      }
    });
    if (error) throw error;
    if (data && data.user) currentSession.user = data.user;
    msg.textContent = t('profile.saved');
    msg.className = 'profile-msg success';
  } catch (err) {
    msg.textContent = err.message || t('profile.saveError');
    msg.className = 'profile-msg error';
  } finally {
    btn.disabled = false;
  }
});

document.getElementById('accountLogoutBtn').addEventListener('click', async () => {
  await sb.auth.signOut();
  showHome();
});

async function loadLibrary() {
  const grid = document.getElementById('libraryGrid');
  grid.innerHTML = '<div class="library-empty">' + t('library.loading') + '</div>';
  const { data, error } = await sb.from('generations').select('*').order('created_at', { ascending: false });
  if (error || !data || !data.length) {
    grid.innerHTML = '<div class="library-empty">' + t('library.emptyHint') + '</div>';
    return;
  }
  grid.innerHTML = data.map(g => {
    const date = new Date(g.created_at).toLocaleDateString(LANG === 'ru' ? 'ru-RU' : 'en-US');
    const label = [g.store_label, g.style_label, g.room_label].filter(Boolean).join(' · ');
    return '<div class="library-card" data-id="' + g.id + '" data-url="' + g.image_url + '">' +
      '<button class="library-delete" type="button" title="Удалить">✕</button>' +
      '<img src="' + g.image_url + '" alt="">' +
      '<div class="library-card-info">' +
        '<div class="library-card-style">' + label + '</div>' +
        '<div class="library-card-date">' + date + '</div>' +
      '</div>' +
    '</div>';
  }).join('');
}

document.getElementById('libraryGrid').addEventListener('click', async e => {
  const delBtn = e.target.closest('.library-delete');
  if (!delBtn) return;
  const card = delBtn.closest('.library-card');
  const id = card.dataset.id;
  const imageUrl = card.dataset.url;
  card.style.opacity = '0.4';
  delBtn.disabled = true;
  await sb.from('generations').delete().eq('id', id);
  try {
    const marker = '/designs/';
    const idx = imageUrl.indexOf(marker);
    if (idx !== -1) {
      const path = decodeURIComponent(imageUrl.slice(idx + marker.length));
      await sb.storage.from('designs').remove([path]);
    }
  } catch (e2) {}
  card.remove();
  if (!document.getElementById('libraryGrid').children.length) {
    document.getElementById('libraryGrid').innerHTML = '<div class="library-empty">' + t('library.emptyShort') + '</div>';
  }
});

async function saveGeneration(blob, styleKey, styleLabel, roomLabel, storeLabel) {
  if (!currentSession) return;
  try {
    const userId = currentSession.user.id;
    const path = userId + '/' + Date.now() + '.jpg';
    const { error: uploadError } = await sb.storage.from('designs').upload(path, blob, { contentType: 'image/jpeg' });
    if (uploadError) throw uploadError;
    const { data: pub } = sb.storage.from('designs').getPublicUrl(path);
    await sb.from('generations').insert({
      user_id: userId,
      image_url: pub.publicUrl,
      style_key: styleKey,
      style_label: styleLabel,
      room_label: roomLabel,
      store_label: storeLabel
    });
  } catch (e) {
    console.error('Не удалось сохранить в историю:', e);
  }
}

