        <div class="about-feat"><div><div class="feat-title" data-i18n="about.feat4Title">Мебель под рукой</div><div class="feat-desc" data-i18n="about.feat4Desc">После генерации ищите похожую мебель в Hoff, Askona, Divan.ru и т.д.</div></div></div>
