<div class="popup-overlay" id="faqModal">
  <div class="popup-box wide">
    <button class="popup-close" onclick="closeModal('faqModal')">✕</button>
    <span class="modal-eyebrow" data-i18n="faq.eyebrow">Вопросы</span>
    <h2 class="modal-title" data-i18n="faq.title">Частые вопросы</h2>
    <div class="faq-list" style="margin-top:32px">
      <details class="faq-item">
        <summary data-i18n="faq.q1">Room Factory — это бесплатно?</summary>
        <p class="faq-answer" data-i18n="faq.a1">Да, создание дизайна интерьера по фото бесплатно. Если появятся платные функции, мы объявим об этом отдельно на сайте.</p>
      </details>
      <details class="faq-item">
        <summary data-i18n="faq.q2">Как загрузить фото комнаты?</summary>
        <p class="faq-answer" data-i18n="faq.a2">Нажмите «Создать дизайн», сфотографируйте комнату или загрузите готовое фото — подходит снимок в любом состоянии, без специальной подготовки.</p>
      </details>
      <details class="faq-item">
        <summary data-i18n="faq.q3">Какие стили интерьера доступны?</summary>
        <p class="faq-answer" data-i18n="faq.a3">Скандинавский, минимализм, лофт, классика, japandi, бохо — и другие варианты на выбор.</p>
      </details>
      <details class="faq-item">
        <summary data-i18n="faq.q4">ИИ сохраняет реальную планировку комнаты?</summary>
        <p class="faq-answer" data-i18n="faq.a4">Да, генерация следует структуре вашей комнаты — расположению окон, дверей и пропорциям помещения.</p>
      </details>
      <details class="faq-item">
        <summary data-i18n="faq.q5">Можно ли сразу купить похожую мебель?</summary>
        <p class="faq-answer" data-i18n="faq.a5">После генерации дизайна сервис подбирает похожую мебель из каталогов Hoff, Askona и Divan.ru.</p>
      </details>
      <details class="faq-item">
        <summary data-i18n="faq.q6">Сколько времени занимает генерация дизайна?</summary>
        <p class="faq-answer" data-i18n="faq.a6">Обычно около 30 секунд с момента загрузки фото до готового результата.</p>
      </details>
    </div>
  </div>
</div>

