<div id="privacyView" style="display:none">
  <div class="account-page">
    <button class="account-back" onclick="showHome()" data-i18n="account.back">← На главную</button>
    <h2 class="account-title" data-i18n="privacy.title">Политика конфиденциальности</h2>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s1Label">Общие положения</span>
      <p class="legal-text" data-i18n="privacy.s1Text">Room Factory (далее — «Сервис») обрабатывает персональные данные пользователей в соответствии с Федеральным законом № 152-ФЗ «О персональных данных». Оператор персональных данных — ИП Вавилов Всеволод Кириллович (ИНН 502983414059, ОГРНИП 326774600676259), контакт: room-factory_help@mail.ru. Используя Сервис, вы соглашаетесь с условиями этой политики.</p>
    </div>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s2Label">Какие данные мы собираем</span>
      <p class="legal-text" data-i18n="privacy.s2Text">Адрес электронной почты, имя и фамилия, номер телефона (если вы его указали), загруженные вами фотографии помещений и сгенерированные на их основе изображения, а также выбранный язык интерфейса.</p>
    </div>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s3Label">Цели обработки</span>
      <p class="legal-text" data-i18n="privacy.s3Text">Данные используются для регистрации и работы личного кабинета, генерации дизайна интерьера, сохранения истории ваших генераций и связи с вами по вопросам работы Сервиса.</p>
    </div>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s4Label">Передача данных третьим лицам</span>
      <p class="legal-text" data-i18n="privacy.s4Text">Мы не продаём и не передаём ваши данные третьим лицам для рекламных целей. Для работы Сервиса данные передаются только сервисам, обеспечивающим его функционирование: хранение аккаунта и загруженных изображений, а также сервису генерации изображений на основе ИИ, обрабатывающему присланные фото для создания дизайна.</p>
    </div>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s5Label">Локальное хранилище и файлы cookie</span>
      <p class="legal-text" data-i18n="privacy.s5Text">Сервис использует локальное хранилище браузера (localStorage), а не рекламные или трекинговые cookie. Там сохраняются: выбранный язык интерфейса и токен вашей сессии, чтобы не запрашивать вход при каждом визите. Эти данные хранятся только в вашем браузере и не передаются рекламным сетям.</p>
    </div>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s6Label">Ваши права</span>
      <p class="legal-text" data-i18n="privacy.s6Text">Вы можете в любой момент запросить доступ к своим данным, их исправление или удаление, а также отозвать согласие на обработку — для этого напишите на room-factory_help@mail.ru.</p>
    </div>

    <div class="account-section">
      <span class="account-section-label" data-i18n="privacy.s7Label">Изменения политики</span>
      <p class="legal-text" data-i18n="privacy.s7Text">Мы можем обновлять эту политику. Актуальная версия всегда доступна на этой странице.</p>
    </div>
  </div>
</div>

