      <p class="legal-text" data-i18n="offer.s2Text">Room Factory — онлайн-сервис, который с помощью искусственного интеллекта создаёт варианты дизайна интерьера на основе загруженной Пользователем фотографии помещения. Оператор предоставляет доступ к функциям Сервиса на условиях настоящей оферты.</p>
