      <p class="legal-text" data-i18n="offer.s7Text">До обращения в суд обязательно предъявление письменной претензии. Ответ на претензию направляется в течение 30 дней. При недостижении согласия спор передаётся в суд по месту нахождения Оператора в соответствии с законодательством РФ.</p>
