    'about.feat4Title': `Furniture at hand`,
    'about.feat4Desc': `After generation, find similar furniture at Hoff, Askona, Divan.ru, etc.`,
    'faq.eyebrow': `FAQ`,
    'faq.title': `Frequently asked questions`,
    'faq.q1': `Is Room Factory free to use?`,
    'faq.a1': `Yes, generating an interior design from your photo is free. If paid features are introduced, we'll announce it separately on the site.`,
    'faq.q2': `How do I upload a photo of my room?`,
    'faq.a2': `Tap "Create design", then photograph your room or upload an existing photo — any condition works, no special prep needed.`,
    'faq.q3': `What interior styles are available?`,
    'faq.a3': `Scandinavian, minimalism, loft, classic, japandi, boho — and more to choose from.`,
    'faq.q4': `Does the AI keep my room's actual layout?`,
    'faq.a4': `Yes, the generated design follows your room's real structure — window and door placement and proportions.`,
    'faq.q5': `Can I buy similar furniture right away?`,
