    'footer.requisites': `Sole proprietor Vavilov Vsevolod Kirillovich · INN 502983414059 · OGRNIP 326774600676259 · Moscow`,
    'cookie.text': `We use browser local storage to keep you signed in and remember your language, and — with your consent — anonymous visit analytics to improve the site. We don't use advertising cookies. More in the <a href="javascript:void(0)" onclick="showPrivacy()">Privacy Policy</a>.`,
    'cookie.accept': `Got it`,
