    'supportChat.toggleTitle': `Chat with support`,
    'supportChat.title': `Room Factory Support`,
    'supportChat.placeholder': `Write a message...`,
    'supportChat.greeting': `Hi! I'm the Room Factory AI assistant. Ask about uploading a photo, choosing a style, finding furniture from the catalog, or anything else about the service — I'll try to help.`,
    'supportChat.typing': `Typing...`,
    'supportChat.error': `Couldn't get a response. Try again, or email room-factory_help@mail.ru.`,
    'privacy.title': `Privacy Policy`,
    'privacy.s1Label': `General`,
    'privacy.s1Text': `Room Factory (the "Service") processes users' personal data in accordance with Federal Law No. 152-FZ "On Personal Data" of the Russian Federation. The personal data operator is Sole proprietor Vavilov Vsevolod Kirillovich (INN 502983414059, OGRNIP 326774600676259), contact: room-factory_help@mail.ru. By using the Service, you agree to this policy.`,
    'privacy.s2Label': `What data we collect`,
    'privacy.s2Text': `Your email address, first and last name, phone number (if you provide one), the room photos you upload and the images generated from them, and your selected interface language.`,
    'privacy.s3Label': `Purpose of processing`,
    'privacy.s3Text': `Data is used to run your account, generate interior designs, save your generation history, and contact you about the Service.`,
    'privacy.s4Label': `Sharing data with third parties`,
    'privacy.s4Text': `We do not sell or share your data with third parties for advertising purposes. Data is only passed to services required to run the Service: account and image storage, and the AI image-generation service that processes uploaded photos to create designs.`,
    'privacy.s5Label': `Local storage and cookies`,
    'privacy.s5Text': `The Service uses browser local storage (localStorage) to store your selected interface language and your session token, so you don't need to sign in on every visit. After you consent to cookies (the banner shown on your first visit), the Service also uses the PostHog web analytics service for anonymous visit and feature-usage statistics — this helps us understand what's working and what needs improving. We do not use advertising or tracking cookies that sell data to third parties. Analytics does not run before you give consent.`,
    'privacy.s6Label': `Your rights`,
    'privacy.s6Text': `You may request access to, correction of, or deletion of your data at any time, and withdraw consent to processing — email room-factory_help@mail.ru.`,
    'privacy.s7Label': `Changes to this policy`,
    'privacy.s7Text': `We may update this policy. The current version is always available on this page.`,
    'offer.title': `Public Offer`,
    'offer.meta': `Operator: Sole proprietor Vavilov Vsevolod Kirillovich, INN 502983414059, OGRNIP 326774600676259`,
    'offer.s1Label': `1. General provisions`,
    'offer.s1Text': `This offer is a proposal by the Operator of the Room Factory website (the "Service") to enter into an agreement on the terms below. By starting to use the Service, the User fully accepts the terms of this offer.`,
    'offer.s2Label': `2. Subject of the agreement`,
    'offer.s2Text': `Room Factory is an online service that uses AI to create interior design variations based on a photo of a room uploaded by the User. The Operator provides access to the Service's features on the terms of this offer.`,
    'offer.s3Label': `3. User responsibilities`,
    'offer.s3Text': `Only upload photos you have the right to use (your own spaces, or spaces you're entitled to photograph and use). Do not use the Service to upload illegal, abusive content, or content that infringes third-party rights.`,
    'offer.s4Label': `4. Generated results`,
    'offer.s4Text': `You may use generated images for personal purposes. Results are created by AI and are for reference only — they are not a professional design project and do not guarantee an exact match to expectations, real-world dimensions, or feasibility of an actual renovation.`,
    'offer.s5Label': `5. Pricing and payment`,
    'offer.s5Text': `The core features of the Service are currently free. If paid features are introduced in the future, their pricing and payment terms will be published on the Site before they go live. Payments are processed by a payment service partner — the Operator does not receive or store card details.`,
    'offer.s6Label': `6. Liability`,
    'offer.s6Text': `The Service is provided "as is." The Operator is not liable for decisions made by the User based on generated images, or for temporary unavailability of the Service.`,
    'offer.s7Label': `7. Dispute resolution`,
    'offer.s7Text': `Before going to court, a written claim must be submitted. A response to the claim is sent within 30 days. If no agreement is reached, the dispute is referred to a court under Russian law, at the Operator's place of registration.`,
    'offer.s8Label': `Operator details`,
    'offer.s8Text': `Sole proprietor Vavilov Vsevolod Kirillovich · INN 502983414059 · OGRNIP 326774600676259 · Moscow · room-factory_help@mail.ru`,
    'consent.title': `Consent to Personal Data Processing`,
    'consent.intro': `By providing personal data on the Room Factory website (the "Site"), the User gives consent to the Site's Operator to process that data on the terms below.`,
    'consent.s1Label': `1. Personal data collected`,
    'consent.s1Text': `First and last name, email address, phone number (if provided), uploaded room photos and the images generated from them. If applicable: date of birth, social media handles. The Operator does not collect or store card details — when payments are enabled, these are processed solely by a payment service partner.`,
    'consent.s2Label': `2. Purpose of processing`,
    'consent.s2Text': `Account registration and management; generating interior designs; saving generation history; contacting the user and handling inquiries; processing payments for paid features (once introduced); sending marketing messages — only with separate consent.`,
    'consent.s3Label': `3. Actions performed with the data`,
    'consent.s3Text': `The Operator may collect, record, organize, accumulate, store, update, use, transfer, anonymize, block, delete, and destroy the data, with or without automated means.`,
    'consent.s4Label': `4. Sharing with third parties`,
    'consent.s4Text': `To run the Site, data is shared with the account storage and authentication provider (Supabase), the AI image-generation service (GigaChat, Sberbank), and, once you consent to cookies, the web analytics service (PostHog) for anonymous usage statistics. Once payments are enabled — with a payment service partner. Data is shared only to the extent needed for these tasks.`,
    'consent.s5Label': `5. Duration of consent`,
    'consent.s5Text': `Consent is valid until withdrawn by the User. To withdraw, email room-factory_help@mail.ru with the subject "Withdrawal of consent to personal data processing".`,
    'consent.s6Label': `6. Data retention period`,
    'consent.s6Text': `Data is retained until the purpose of its processing is achieved, unless a different period is set by law or agreement. Once the purpose is achieved, data is deleted or anonymized.`,
    'consent.s7Label': `7. Confirmation of consent`,
    'consent.s7Text': `Consent is deemed given upon registering on the Site, filling in account forms, or submitting any contact form on the Site.`,
    'auth.tabLogin': `Log in`,
    'auth.tabSignup': `Sign up`,
    'authPasswordPlaceholder': `Password`,
    'authSubmitLogin': `Log in`,
    'authSubmitSignup': `Sign up`,
    'authSuccess': `Check your email to confirm your registration.`,
    'authErrorFallback': `Something went wrong. Please try again.`,
    'auth.forgotPassword': `Forgot password?`,
    'auth.consentText': `I agree to the <a href="javascript:void(0)" onclick="showPrivacy()">privacy policy</a> and <a href="javascript:void(0)" onclick="showConsent()">consent to personal data processing</a>`,
    'auth.consentRequired': `You need to accept the personal data processing terms`,
    'auth.backToLogin': `← Back to login`,
