let file = null;
let generating = false;
let apartmentMode = false;
let apartmentFiles = [];

function enterApartmentMode() {
  apartmentMode = true;
  showHome();
  document.getElementById('apartmentBanner').style.display = 'block';
  document.getElementById('apartmentPhotosSection').style.display = 'block';
  document.getElementById('styleSection').style.display = 'none';
  document.getElementById('styleDivider').style.display = 'none';
  document.getElementById('colorSection').style.display = 'none';
  document.getElementById('colorDivider').style.display = 'none';
  document.getElementById('uploadZoneText').textContent = t('apartment.uploadTextTarget');
  document.getElementById('generator').scrollIntoView({ behavior: 'smooth' });
}
function exitApartmentMode() {
  apartmentMode = false;
  apartmentFiles = [];
  document.getElementById('apartmentBanner').style.display = 'none';
  document.getElementById('apartmentPhotosSection').style.display = 'none';
  document.getElementById('styleSection').style.display = '';
  document.getElementById('styleDivider').style.display = '';
  document.getElementById('colorSection').style.display = '';
  document.getElementById('colorDivider').style.display = '';
  document.getElementById('uploadZoneText').textContent = t('upload.text');
  document.getElementById('apartmentFileInput').value = '';
  const zone = document.getElementById('apartmentUploadZone');
  zone.classList.remove('has-image');
  const list = zone.querySelector('.apartment-files-list');
  if (list) list.remove();
}
document.getElementById('apartmentFileInput').addEventListener('change', e => {
  apartmentFiles = Array.from(e.target.files);
  const zone = document.getElementById('apartmentUploadZone');
  let list = zone.querySelector('.apartment-files-list');
  if (!list) {
    list = document.createElement('p');
    list.className = 'apartment-files-list';
    zone.appendChild(list);
  }
  list.textContent = t('apartment.filesChosen') + ' ' + apartmentFiles.length;
});
